    for (let i = pos; i < at; i++) result.push(a[i]);
    let cur = at;
    for (const line of lines) {
      const p = line[0];
      if (p === ' ') result.push(a[cur++]);
      else if (p === '-') cur++;
      else result.push(line.slice(1));
    }
    pos = cur;
  }
  for (let i = pos; i < a.length; i++) result.push(a[i]);
  return result;
}

