'use strict';
const assert = require('node:assert/strict');
const { diffLines, unifiedHunks, applyHunks } = require('./src/diff');

function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
  return dp[a.length][b.length];
}
let seed = 12345;
const rnd = (n) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
const alpha = ['', 'x', 'y', '-x', '+y', ' z', '__proto__', 'x'];
const gen = () => Array.from({ length: rnd(14) }, () => alpha[rnd(rnd(2) ? 3 : alpha.length)]);

for (let t = 0; t < 30000; t++) {
  const a = gen(), b = gen();
  const ac = a.slice(), bc = b.slice();
  const s = diffLines(a, b);
  assert.deepEqual(s, diffLines(a, b));
  assert.deepEqual(s.filter((e) => e.op !== 'insert').map((e) => e.line), a);
  assert.deepEqual(s.filter((e) => e.op !== 'delete').map((e) => e.line), b);
  assert.equal(s.filter((e) => e.op !== 'equal').length, a.length + b.length - 2 * lcs(a, b));
  for (let i = 1; i < s.length; i++) assert.ok(!(s[i - 1].op === 'insert' && s[i].op === 'delete'));
  for (const context of [0, 1, 2, 3]) {
    const h = unifiedHunks(a, b, { context });
    assert.deepEqual(applyHunks(a, h), b);
    if (a.join('\n') === b.join('\n') && a.length === b.length) assert.deepEqual(h, []);
    // coordinate check vs reconstruction
    for (const hk of h) {
      const old = hk.lines.filter((l) => l[0] !== '+').map((l) => l.slice(1));
      const nw = hk.lines.filter((l) => l[0] !== '-').map((l) => l.slice(1));
      assert.equal(hk.oldLines, old.length); assert.equal(hk.newLines, nw.length);
      const os = hk.oldLines ? hk.oldStart - 1 : hk.oldStart;
      const ns = hk.newLines ? hk.newStart - 1 : hk.newStart;
      assert.deepEqual(a.slice(os, os + old.length), old);
      assert.deepEqual(b.slice(ns, ns + nw.length), nw);
    }
    for (let i = 1; i < h.length; i++) {
      const prevEnd = h[i - 1].oldStart + h[i - 1].oldLines - (h[i - 1].oldLines ? 1 : 0);
      assert.ok(h[i].oldStart - prevEnd - 1 > 0, 'gaps should exceed 2*context');
    }
    if (h.length) {
      const bad = structuredClone(h);
      const idx = rnd(bad.length);
      const li = bad[idx].lines.findIndex((l) => l[0] !== '+');
      if (li >= 0) { bad[idx].lines[li] = bad[idx].lines[li][0] + 'NOPE'; assert.throws(() => applyHunks(a, bad), new RegExp(`hunk ${idx} does not apply`)); }
    }
  }
  assert.deepEqual(a, ac); assert.deepEqual(b, bc);
}

// Performance: 20k lines, small and repetitive changes.
const big = Array.from({ length: 20000 }, (_, i) => (i % 7 === 0 ? '' : `line ${i % 50}`));
const big2 = big.slice(); big2.splice(100, 3, 'a', 'b'); big2.splice(15000, 0, 'q'); big2[19999] = 'end';
let t0 = performance.now();
const hh = unifiedHunks(big, big2);
assert.deepEqual(applyHunks(big, hh), big2);
console.log('small change 20k ms', (performance.now() - t0).toFixed(1));
t0 = performance.now(); diffLines(big, big.slice()); console.log('identical ms', (performance.now() - t0).toFixed(1));
const rep = new Array(20000).fill('same'); const rep2 = rep.slice(); rep2.splice(10000, 5);
t0 = performance.now(); assert.equal(diffLines(rep, rep2).filter((e) => e.op !== 'equal').length, 5); console.log('repetitive ms', (performance.now() - t0).toFixed(1));
const x = Array.from({ length: 5000 }, (_, i) => 'a' + i), y = Array.from({ length: 5000 }, (_, i) => 'b' + i);
t0 = performance.now(); diffLines(x, y); console.log('disjoint 5k ms', (performance.now() - t0).toFixed(1));
console.log('ok');
